        var category = Combo(new[] { "Toutes les catégories" }.Concat(vault.Index.Categories)); var search = new TextBox { MinWidth = 260 }; var table = new DataGrid { Height = 320, SelectionMode = DataGridSelectionMode.Single }; table.Columns.Add(new DataGridTextColumn { Header = "Document", Binding = new Binding("Name"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) }); table.Columns.Add(new DataGridTextColumn { Header = "Catégorie", Binding = new Binding("Category"), Width = 150 }); table.Columns.Add(new DataGridTextColumn { Header = "Taille", Binding = new Binding("Poids"), Width = 80 }); void Filter() { if (!vault.IsOpen) return; string filter = search.Text.Trim(); table.ItemsSource = vault.Index.Files.Where(f => (category.SelectedIndex == 0 || f.Category == (string)category.SelectedItem) && (filter.Length == 0 || f.Name.Contains(filter, StringComparison.CurrentCultureIgnoreCase))).ToList(); }
