    void ShowVaultLocked() { var profiles = Directory.GetDirectories(VaultRoot).Where(d => File.Exists(Path.Combine(d, "vault.json"))).Select(d => new VaultProfile(Storage.Read(Path.Combine(d, "vault.json"), new VaultEnvelope()).Label, d)).ToList(); var selector = new ComboBox { ItemsSource = profiles, SelectedIndex = profiles.Count > 0 ? 0 : -1, MinWidth = 280 }; var password = new PasswordBox(); var recovery = new CheckBox { Content = "Utiliser ma clé de récupération à la place de la phrase secrète" }; Page.Children.Add(Text("Choisissez votre profil local", 16, true)); Page.Children.Add(selector); Page.Children.Add(Text("Phrase secrète (ou clé de récupération)", 14)); Page.Children.Add(password); Page.Children.Add(recovery); Page.Children.Add(Row(AsyncButton("Déverrouiller mon coffre", async () => { if (DateTime.UtcNow < unlockAfter) throw new Exception("Veuillez patienter 30 secondes avant de réessayer."); if (selector.SelectedItem is not VaultProfile profile) throw new Exception("Créez votre coffre ou restaurez une sauvegarde."); bool useRecovery = recovery.IsChecked == true; string secret = password.Password; password.Clear(); busy = true; try { await Task.Run(() => vault.Unlock(profile.Path, secret, useRecovery)); failedUnlocks = 0; activity = DateTime.UtcNow; busy = false; ShowVault(); } catch (CryptographicException) { if (++failedUnlocks >= 3) { unlockAfter = DateTime.UtcNow.AddSeconds(30); failedUnlocks = 0; } throw new Exception("Phrase secrète ou clé incorrecte, ou coffre endommagé. Aucun document n’a été modifié."); } finally { busy = false; } }, true), Button("Créer mon coffre", CreateVault), Button("Restaurer une sauvegarde", () => { var dialog = new OpenFileDialog { Filter = "Sauvegarde de coffre|*.cremavault;*.zip" }; if (dialog.ShowDialog() == true) { VaultEngine.Restore(dialog.FileName, VaultRoot); ShowVault(); Info("Sauvegarde restaurée", "Choisissez le coffre restauré puis déverrouillez-le avec sa phrase secrète ou sa clé de récupération."); } }))); Page.Children.Add(Text("Une phrase secrète d’au moins 12 caractères protège le coffre. Une clé de récupération permet de retrouver l’accès en cas d’oubli. Sans l’une de ces deux clés, les documents ne peuvent pas être récupérés.", 14, false, "#607087", new Thickness(0, 20, 0, 12))); Page.Children.Add(Text("Pas de compte en ligne : chaque personne crée son propre coffre. Les fichiers et les noms des documents sont chiffrés. Pensez aux sauvegardes sur un autre support.", 13, false, "#607087")); }
    static string? Prompt(string title, string hint) { var window = new Window { Title = title, Width = 470, Height = 230, WindowStartupLocation = WindowStartupLocation.CenterScreen, ResizeMode = ResizeMode.NoResize }; var panel = new StackPanel { Margin = new Thickness(24) }; panel.Children.Add(Text(hint, 13, false, "#607087")); var field = new TextBox(); panel.Children.Add(field); var button = new Button { Content = "Valider" }; button.Click += (_, _) => { if (string.IsNullOrWhiteSpace(field.Text)) return; window.DialogResult = true; }; panel.Children.Add(button); window.Content = panel; return window.ShowDialog() == true ? field.Text.Trim() : null; }
    void CreateVault() { var window = new Window { Owner = this, Title = "Créer un coffre", Width = 520, Height = 460, WindowStartupLocation = WindowStartupLocation.CenterOwner, ResizeMode = ResizeMode.NoResize }; var panel = new StackPanel { Margin = new Thickness(28) }; panel.Children.Add(Text("Votre espace personnel", 24, true)); panel.Children.Add(Text("Nom du profil local", 13)); var name = new TextBox(); panel.Children.Add(name); panel.Children.Add(Text("Phrase secrète : au moins 12 caractères", 13)); var password = new PasswordBox(); panel.Children.Add(password); panel.Children.Add(Text("Confirmez la phrase secrète", 13)); var confirm = new PasswordBox(); panel.Children.Add(confirm); string? recoveryKey = null; panel.Children.Add(AsyncButton("Créer mon coffre chiffré", async () => { if (name.Text.Trim().Length == 0) throw new Exception("Indiquez un nom de profil."); if (password.Password != confirm.Password) throw new Exception("Les phrases secrètes sont différentes."); string label = name.Text.Trim(), secret = password.Password; busy = true; try { recoveryKey = await Task.Run(() => vault.Create(VaultRoot, label, secret)); } finally { busy = false; } password.Clear(); confirm.Clear(); window.DialogResult = true; }, true)); window.Content = panel; if (window.ShowDialog() == true && recoveryKey is not null) { var recovery = new Window { Owner = this, Title = "Conservez votre clé de récupération", Width = 640, Height = 430, WindowStartupLocation = WindowStartupLocation.CenterOwner }; var body = new StackPanel { Margin = new Thickness(28) }; body.Children.Add(Text("Votre clé de récupération", 24, true)); body.Children.Add(Text("Gardez-la séparément du coffre et de sa sauvegarde. Elle permet de déverrouiller tous les documents. Ne la partagez pas.", 14)); body.Children.Add(new TextBox { Text = recoveryKey, IsReadOnly = true, TextWrapping = TextWrapping.Wrap }); bool acknowledged = false; body.Children.Add(Button("Enregistrer la clé dans un fichier", () => { var di