    void ChangeVaultPassword() { var window = new Window { Owner = this, Title = "Nouvelle phrase secrète", Width = 480, Height = 310, WindowStartupLocation = WindowStartupLocation.CenterOwner }; var body = new StackPanel { Margin = new Thickness(24) }; body.Children.Add(Text("Au moins 12 caractères. La clé de récupération reste valable.", 14)); var a = new PasswordBox(); var b = new PasswordBox(); body.Children.Add(a); body.Children.Add(b); body.Children.Add(AsyncButton("Enregistrer", async () => { if (a.Password != b.Password) throw new Exception("Les phrases secrètes sont différentes."); string secret = a.Password; busy = true; try { await Task.Run(() => vault.ChangePassword(secret)); } finally { busy = false; } a.Clear(); b.Clear(); window.DialogResult = true; }, true)); window.Content = body; window.ShowDialog(); }
    void PreviewVaultFile(VaultFile file) { var data = vault.Read(file); try { var window = new Window { Owner = this, Title = file.Name + " — aperçu protégé", Width = 900, Height = 760, WindowStartupLocation = WindowStartupLocation.CenterOwner }; var panel = new DockPanel { Margin = new Thickness(16) }; var help = Text("Aperçu en mémoire : aucun fichier déchiffré temporaire n’est créé.", 12, false, "#607087"); DockPanel.SetDock(help, Dock.Top); panel.Children.Add(help); if (FileEngine.IsPdf(file.Name) || FileEngine.IsImage(file.Name)) { var img = new Image { Stretch = Stretch.Uniform }; var bar = new WrapPanel(); DockPanel.SetDock(bar, Dock.Top); panel.Children.Add(bar); panel.Children.Add(img); int page = 0, count = 1; byte[] GetImage() { if (FileEngine.IsPdf(file.Name)) { using var stream = new MemoryStream(data); using var bitmap = PDFtoImage.Conversion.ToImage(stream, page: page, options: new PDFtoImage.RenderOptions(Dpi: 110)); using var encoded = bitmap.Encode(SKEncodedImageFormat.Png, 100); return encoded.ToArray(); } using var picture = new ImageMagick.MagickImage(data); picture.AutoOrient(); picture.Resize(new ImageMagick.MagickGeometry(1600, 1600) { Greater = true }); return picture.ToByteArray(ImageMagick.MagickFormat.Png); } if (FileEngine.IsPdf(file.Name)) { using var stream = new MemoryStream(data); using var pdf = PdfSharp.Pdf.IO.PdfReader.Open(stream, PdfSharp.Pdf.IO.PdfDocumentOpenMode.Import); count = pdf.PageCount; } var counter = Text(""); void Render() { var bytes = GetImage(); using var stream = new MemoryStream(bytes); var bitmap = new BitmapImage(); bitmap.BeginInit(); bitmap.CacheOption = BitmapCacheOption.OnLoad; bitmap.StreamSource = stream; bitmap.EndInit(); bitmap.Freeze(); img.Source = bitmap; counter.Text = $"Page {page + 1} / {count}"; CryptographicOperations.ZeroMemory(bytes); } bar.Children.Add(Button("←", () => { if (page > 0) { page--; Render(); } })); bar.Children.Add(counter); bar.Children.Add(Button("→", () => { if (page < cou